import { QueryClient } from '@tanstack/react-query'
import { shouldRetryQuery } from './retry'

/**
 * The single owner of server state. Every screen reads through it, and a
 * server-sent event does nothing to it but invalidate a key.
 */
export const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      retry: shouldRetryQuery,

      // Declared rather than inherited: it is the deliberate compensation for the Accounts
      // and Transactions screens sitting outside the live-update scope, so a list nobody
      // was looking at is not silently out of date.
      refetchOnWindowFocus: true,

      // No `staleTime` on purpose — any non-zero value would defeat the line above, since
      // a focus only refetches what is already stale.
    },
  },
})
